<main class="public-form-page"><div class="public-form-context"><span class="pill soft"><?= icon('form') ?><?= e($form['project_name']) ?></span><h1><?= e($form['title']) ?></h1><p><?= e($form['description']) ?></p></div><section class="panel public-form-panel"><?php if($submitted): ?><div class="empty-state"><span class="success-orb"><?= icon('check') ?></span><h2>Le premier pas est fait.</h2><p>Votre demande a bien rejoint notre équipe.<br>Merci de nous aider à avancer.</p><a href="/f/<?= e($token) ?>" class="button subtle">Envoyer une autre demande</a></div><?php else: ?><form method="post" enctype="multipart/form-data" class="stack" action="/f/<?= e($token) ?>"><?= csrf() ?><label>Votre adresse e-mail<input type="email" name="email" required maxlength="190" placeholder="vous@entreprise.fr" autocomplete="email"><small>Pour permettre à l’équipe <?= e(App\Core\Company::name()) ?> de vous recontacter.</small></label><div class="honeypot" aria-hidden="true"><label>Site web<input name="website" tabindex="-1" autocomplete="off"></label></div><?php foreach($form['fields'] as $field): $key=$field['key']; ?><label data-public-field="<?= e($key) ?>" <?= $field['condition']?'data-condition-field="'.e($field['condition']['field']).'" data-condition-value="'.e($field['condition']['value']).'"':'' ?>><?= e($field['label']) ?><?= $field['required']?' <span class="required">*</span>':'' ?><?php if($key==='description'): ?><textarea name="description" rows="5" <?= $field['required']?'required':'' ?>></textarea><?php elseif($key==='priority'): ?><select name="priority" <?= $field['required']?'required':'' ?>><?php foreach(App\Models\Ticket::PRIORITIES as $v=>$l): ?><option value="<?= e($v) ?>" <?= $v==='medium'?'selected':'' ?>><?= e($l) ?></option><?php endforeach; ?></select><?php elseif($key==='attachment'): ?><input type="file" name="attachment" <?= $field['required']?'required':'' ?>><small><?= (int)env('UPLOAD_MAX_MB','10') ?> Mo maximum. Images, PDF, texte, CSV et documents Office.</small><?php else: ?><input name="<?= e($key) ?>" type="<?= $key==='due_date'?'date':'text' ?>" <?= $field['required']?'required':'' ?> <?= $key==='title'?'maxlength="240"':'' ?>><?php endif; ?></label><?php endforeach; ?><button class="button primary wide">Envoyer ma demande <?= icon('arrow') ?></button><p class="help-text">Votre demande et vos coordonnées sont transmises à l’équipe <?= e(App\Core\Company::name()) ?> pour son traitement.</p></form><?php endif; ?></section></main>
